<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Customer dashboard | Sun Son Solar</title><link rel="stylesheet" href="<?= base_url('style1.css') ?>"></head><body class="portal-body"><header class="portal-header"><a href="<?= site_url('/') ?>"><strong>Sun Son Solar</strong></a><span>Welcome, <?= esc($profile['first_name']) ?></span><a href="<?= site_url('logout') ?>">Log out</a></header><main class="portal-main"><h1>Your solar service dashboard</h1><?php if ($msg=session()->getFlashdata('message')): ?><p class="notice"><?= esc($msg) ?></p><?php endif ?><?php if ($msg=session()->getFlashdata('error')): ?><p class="notice notice--error"><?= esc($msg) ?></p><?php endif ?>
<div class="portal-grid"><section class="portal-card"><h2>Request a service</h2><form method="post" action="<?= site_url('booking') ?>"><?= csrf_field() ?><label>Service<select name="service_id" required><?php foreach($services as $service): ?><option value="<?= (int)$service['service_id'] ?>"><?= esc($service['service_name']) ?><?= $service['base_price']!==null?' · ₱'.number_format((float)$service['base_price'],2):'' ?></option><?php endforeach ?></select></label><label>Preferred date and time<input type="datetime-local" name="scheduled_at" required></label><label>Notes<textarea name="customer_notes" rows="3"></textarea></label><button class="auth-submit">Request appointment</button></form></section>
<section class="portal-card"><h2>Notifications and updates</h2><?php foreach($notifications as $item): ?><article class="list-row"><strong><?= esc($item['title']) ?></strong><p><?= esc($item['message']) ?></p><small><?= esc($item['created_at']) ?></small></article><?php endforeach ?><?php foreach($announcements as $item): ?><article class="list-row"><strong><?= esc($item['title']) ?></strong><p><?= esc($item['message']) ?></p></article><?php endforeach ?><?php if (!$notifications && !$announcements): ?><p>No updates yet.</p><?php endif ?></section>
<section class="portal-card portal-card--wide"><h2>Upcoming and requested services</h2><?php $upcoming=array_filter($bookings,fn($b)=>!in_array($b['status'],['completed','cancelled','declined'],true)); if (!$upcoming): ?><p>No upcoming services. Request an appointment to get started.</p><?php else: ?><div class="table-wrap"><table><thead><tr><th>Service</th><th>When</th><th>Status</th><th>Technician</th><th></th></tr></thead><tbody><?php foreach($upcoming as $booking): ?><tr><td><?= esc($booking['service_name']) ?></td><td><?= esc($booking['scheduled_at']) ?></td><td><span class="status-pill"><?= esc(str_replace('_',' ',$booking['status'])) ?></span></td><td><?= esc(trim(($booking['tech_first']??'').' '.($booking['tech_last']??'')) ?: 'To be assigned') ?></td><td><?php if($booking['status']==='requested'): ?><form method="post" action="<?= site_url('booking/'.(int)$booking['booking_id'].'/cancel') ?>"><?= csrf_field() ?><button class="small-button">Cancel</button></form><?php endif ?></td></tr><?php endforeach ?></tbody></table></div><?php endif ?></section>
<section class="portal-card"><h2>Service history and receipts</h2><?php if(!$history): ?><p>Completed services and payments will appear here.</p><?php else: foreach($history as $item): ?><article class="list-row"><strong><?= esc($item['service_name']) ?> · <?= esc($item['scheduled_at']) ?></strong><p><?= esc($item['status']) ?> · <?php if($item['amount']!==null): ?>₱<?= number_format((float)$item['amount'],2) ?> (<?= esc($item['payment_status']) ?>)<?php else: ?>No payment recorded yet<?php endif ?></p><?php if($item['reference_number']): ?><small>Receipt/reference <?= esc($item['reference_number']) ?></small><?php endif ?></article><?php endforeach; endif ?></section>
<section class="portal-card"><h2>Contact support</h2><form method="post" action="<?= site_url('support') ?>"><?= csrf_field() ?><label>Subject<input name="subject" maxlength="160" required></label><label>How can we help?<textarea name="message" rows="3" required></textarea></label><button class="auth-submit">Send support request</button></form><?php foreach($tickets as $ticket): ?><p class="list-row"><strong><?= esc($ticket['subject']) ?></strong> · <?= esc($ticket['status']) ?></p><?php endforeach ?></section>
<section class="portal-card portal-card--wide"><h2>Your profile</h2><form class="profile-form" method="post" action="<?= site_url('profile') ?>"><?= csrf_field() ?><div class="signup-grid"><?php foreach(['first_name'=>'First name','middle_name'=>'Middle name','last_name'=>'Last name','birthdate'=>'Birthdate','gender'=>'Gender','email'=>'Email','phone_number'=>'Phone','address'=>'Address'] as $key=>$label): ?><label><?= esc($label) ?><?php if($key==='gender'): ?><select name="gender"><option <?= $profile['gender']==='Female'?'selected':'' ?>>Female</option><option <?= $profile['gender']==='Male'?'selected':'' ?>>Male</option><option <?= $profile['gender']==='Other'?'selected':'' ?>>Other</option></select><?php elseif($key==='address'): ?><textarea name="address" required><?= esc($profile[$key]) ?></textarea><?php else: ?><input name="<?= esc($key) ?>" value="<?= esc($profile[$key]) ?>" <?= $key==='birthdate'?'type="date"':($key==='email'?'type="email"':'') ?> required><?php endif ?></label><?php endforeach ?></div><h3>Change password (optional)</h3><div class="signup-grid"><label>Current password<input type="password" name="current_password" autocomplete="current-password"></label><label>New password, at least 12 characters<input type="password" name="new_password" autocomplete="new-password" minlength="12"></label></div><button class="auth-submit">Save profile</button></form></section></div></main></body></html>
